-- Technology track: Python Foundations (course 2 of the tech pathway).
-- A complete beginner-to-confident-novice Python course built on
-- Carnegie-Mellon-style pedagogy: every lesson moves theory -> guided
-- practice -> independent practice, with worked examples traced line by
-- line, retrieval warm-ups, deliberate-practice tasks with expected
-- outputs, common-misconception debriefs, and exit tickets. Assessment is
-- layered: a diagnostic, two checkpoints, an applied project, and a final.
-- All content is original, targets Python 3.12+, and uses no external
-- libraries. Fixed UUIDs and guarded inserts make the file idempotent:
-- safe to re-run at any time.

-- ============ Python Foundations ============
insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values (
